 document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>run(async()=>{const {content:c}=await call('preview',{id:b.dataset.preview});const modal=document.createElement('dialog');modal.innerHTML=`<form method="dialog"><button class="secondary">Close preview</button></form><h2>${esc(c.title)}</h2>${(c.pages||[]).map((p,i)=>`<h3>Page ${i+1}</h3><p>${esc(p)}</p>`).join('')}<h2>Questions & teacher answers</h2>${c.questions.map(q=>`<details><summary>${esc(q.prompt)}</summary><p>${q.choices.map(esc).join(' · ')}</p><b>Answer: ${esc(q.choices[q.correct])}</b><p>${esc(q.explanation)}</p></details>`).join('')}`;document.body.append(modal);modal.addEventListener('close',()=>modal.remove());modal.showModal()},b));
