 document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{const t=state.tasks.find(t=>t.id===b.dataset.task);if(productService!==t.service){const u=new URL(link(t.service==='reader'?'OneReader':'OneMaths'));u.searchParams.set('view','homework');location.href=u.href;return}service=t.service;view='task';app.querySelector('.main').innerHTML=heading(esc(t.title),`Target: ${t.points} ${service==='reader'?'Star':'Power'} Points`,'<button id="backTasks">Back</button>')+`<section class="card">${t.items.map(id=>`<div class="row"><b>${esc(state.catalog.find(c=>c.id===id)?.title||'Content unavailable')}</b><button data-start="${esc(id)}">Open</button></div>`).join('')}</section>`;by('backTasks').onclick=()=>goto('homework');document.querySelectorAll('[data-start]').forEach(btn=>btn.onclick=()=>run(()=>openItem(btn.dataset.start,t.id),btn))});
 by('applyFilter')?.addEventListener('click',()=>{search=by('search').value;filter=by('filter').value;showShort=!!by('shortReads')?.checked;render()});by('taskService')?.addEventListener('change',e=>{service=e.target.value;render()});
 by('taskForm')?.addEventListener('submit',e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target),items=f.getAll('item'),release=new Date(f.get('release')),due=new Date(f.get('due')),points=Number(f.get('points'));if(!items.length||items.length>20)throw Error('Choose 1–20 content items.');if(due<=release)throw Error('The deadline must be later than release.');const max=items.reduce((n,id)=>{const c=state.catalog.find(v=>v.id===id);return n+(service==='maths'?40:(c?.long?Math.ceil(c.pagesCount/5):1)*(state.settings.starReader?20:10))},0);if(points>max)throw Error(`These items can award at most ${max} points. Lower the target or add items.`);await call('task',{title:f.get('title'),class:f.get('class'),service:f.get('service')||productService,items,points,release:release.toISOString(),due:due.toISOString()});await refresh();toast('Homework scheduled. It appears to students at the release time.')},e.submitter)});
 by('settingsForm')?.addEventListener('submit',e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target);await call('settings',{board:f.get('board'),years:f.getAll('year').map(Number),ready:f.has('ready'),college:f.has('college'),starReader:f.has('starReader'),gothic:f.has('gothic')});await refresh();toast('School settings saved.')},e.submitter)});
 by('sync')?.addEventListener('click',e=>run(async()=>{const r=await call('sync');await refresh();toast(`${r.count} students connected.`)},e.currentTarget));
