 document.querySelectorAll('[data-rotate]').forEach(b=>b.onclick=()=>{if(confirm('Replace this student’s code? Their previous code will stop working.'))run(async()=>{const r=await call('rotate',{student:b.dataset.rotate});download('OneHome-private-code.txt',r.code);toast('New private code downloaded.')},b)});
 by('reportClass')?.addEventListener('change',e=>{filter=e.target.value;render()});by('exportReport')?.addEventListener('click',()=>{download('OneHome-class-progress.csv',csv([['Student','Year','Last login','Reading level','Recorded reading age','Assessment source','Star Points','Power Points','Active minutes (estimate)'],...state.students.filter(s=>!filter||s.class_ids.includes(filter)).map(s=>[name(s),s.year,s.last_login||'',state.progress.find(p=>p.student_id===s.id&&p.id==='reading-check')?.data.level||'',s.reading_age||'',s.age_source||'',...['reader','maths'].map(svc=>state.awards.filter(a=>a.student_id===s.id&&a.service===svc).reduce((n,a)=>n+a.points,0)),studyMinutes(s.id)])]),'text/csv')});
 document.querySelectorAll('[data-age]').forEach(b=>b.onclick=()=>{const age=prompt('Reading age from your school-approved assessment (for example 12y 4m):');if(age===null)return;const source=prompt('Assessment name and date (required):');if(!source)return;run(async()=>{await call('reading_age',{student:b.dataset.age,age,source});await refresh()},b)});
 document.querySelectorAll('[data-college]').forEach(b=>b.onclick=()=>run(async()=>{await call('college_class',{class:b.dataset.college,enabled:state.settings.collegeOff.includes(b.dataset.college)});await refresh()},b));
 for(const [id,key] of [['fontSize','size'],['pageColour','colour'],['lineSpacing','spacing']])by(id)?.addEventListener('change',e=>{reading[key]=key==='colour'?e.target.value:Number(e.target.value);localStorage.setItem('onehome-reading-style',JSON.stringify(reading));render()});by('guide')?.addEventListener('click',()=>{reading.guide=!reading.guide;render()});by('break')?.addEventListener('click',()=>{paused=true;by('readingPaper').innerHTML='<p>Take a moment away from the screen. Your page is saved.</p><button id="resumeReading">Resume reading</button>';by('resumeReading').onclick=()=>{paused=false;lastActivity=Date.now();render()}});
 by('prevPage')?.addEventListener('click',e=>run(async()=>{page--;opened.pageText=(await call('page',{id:opened.id,page})).text;render()},e.currentTarget));by('nextPage')?.addEventListener('click',e=>run(async()=>{if(checkpointDue()){view='quiz';question=opened.content.long?opened.content.questions.findIndex(q=>q.pageEnd===page):0}else if(page<(opened.content.pagesCount||5)-1){const next=page+1;opened.pageText=(await call('page',{id:opened.id,page:next})).text;page=next}else{goto('library');return}render()},e.currentTarget));

 by('answerForm')?.addEventListener('submit',e=>{e.preventDefault();run(async()=>{feedback=await call('answer',{id:opened.id,question,answer:Number(new FormData(e.target).get('answer')),...(opened.task?{task:opened.task}:{})});opened.progress=feedback.progress;render();if(feedback.correct)celebrate()},e.submitter)});by('prevQuestion')?.addEventListener('click',()=>{question--;feedback=null;render()});by('nextQuestion')?.addEventListener('click',()=>run(async()=>{if(service==='reader'&&(!opened.content.questions[question+1]||opened.content.questions[question+1].checkpoint!==opened.content.questions[question].checkpoint)){if(page<(opened.content.pagesCount||5)-1){const next=page+1;opened.pageText=(await call('page',{id:opened.id,page:next})).text;page=next;view='read'}else{goto('library');return}}else if(question===opened.content.questions.length-1){goto('homework');return}else question++;feedback=null;render()}));
 function collectTest(){const f=new FormData(by('testForm'));for(const [k,v] of f)assessmentAnswers[k.slice(1)]=Number(v)}
 by('saveTest')?.addEventListener('click',e=>run(async()=>{collectTest();await call('test_save',{id:'reading-check',answers:assessmentAnswers,submit:false});view='service';opened=null;await refresh();toast('Reading check saved.')},e.currentTarget));
 by('testForm')?.addEventListener('submit',e=>{e.preventDefault();run(async()=>{collectTest();const r=await call('test_save',{id:'reading-check',answers:assessmentAnswers,submit:section===4});if(section<4){section++;render();window.scrollTo(0,0)}else{opened=null;view='service';await refresh();toast(`Reading check complete: ${r.level}. You can now choose a book.`)}},e.submitter)});
