function available(svc){return Math.max(0,(wallet?.earned?.[svc]||0)-(wallet?.spent?.[svc]||0)-(wallet?.saved?.[svc]||0))}
function petCard(){const fed=Date.now()-new Date(wallet?.fed||0).getTime()<86400000,water=Date.now()-new Date(wallet?.water||0).getTime()<86400000;const reward=rewards.find(r=>r.id===wallet?.equipped?.pet);return `<section class="card pet-card"><div class="pet-art"><img src="pet-fox.svg" alt="Pip, your friendly fox study companion">${reward?`<span class="pet-accessory" style="background:${reward.colour}">${esc(reward.name)}</span>`:''}</div><div><span class="eyebrow">Your study buddy</span><h2>Pip the fox</h2><p>${fed&&water?'Ready for a little learning together.':'A snack and a drink help Pip feel ready.'}</p><div class="toolbar space"><button data-care="fed" class="secondary">${fed?'Fed today':'Give food'}</button><button data-care="water" class="secondary">${water?'Water topped up':'Give water'}</button></div><small>Care is free. Your normal hints always work.</small>${view==='quiz'&&service==='maths'?'<button id="petHelp" class="quiet space">Ask Pip for a bonus hint</button>':''}</div></section>`}
function walletCard(){return `<section class="card"><span class="eyebrow">Spend a little. Save a little.</span><h2>Your points</h2><div class="grid space">${['reader','maths'].map(s=>`<div class="balance"><small>${s==='reader'?'Star':'Power'} Points</small><strong>${available(s)}</strong><small>${wallet?.saved?.[s]||0} safely saved</small></div>`).join('')}</div><button class="secondary space" data-view="wallet">Manage savings</button></section>`}
function walletPage(){return heading('Points & savings','Your homework keeps every point you earn, even after you spend it.')+walletCard()+`<div class="grid space">${['reader','maths'].map(s=>`<form class="card" data-saving="${s}"><h2>${s==='reader'?'Star':'Power'} savings</h2><p>Available ${available(s)} · Saved ${wallet?.saved?.[s]||0} · Spent ${wallet?.spent?.[s]||0}</p><label class="space">Amount<input type="number" name="amount" min="1" max="100000" required></label><div class="toolbar"><button name="direction" value="save">Move to savings</button><button name="direction" value="withdraw" class="secondary">Withdraw</button></div></form>`).join('')}</div><p class="space">Virtual rewards only. No real money, interest, trading or random prizes.</p>`}
function shopPage(){return heading('The little reward shop','30 optional rewards. Buy once, then use whenever you like.')+walletCard()+`<div class="book-grid space">${rewards.map(r=>{const own=wallet?.owned?.includes(r.id),equipped=wallet?.equipped?.[r.category]===r.id;return `<article class="card reward"><div class="reward-art" style="background:${r.colour}"><img class="icon" src="icon-${r.service==='reader'?'reader':'maths'}.svg" alt=""></div><h3>${esc(r.name)}</h3><p>${r.cost} ${r.service==='reader'?'Star':'Power'} Points</p><small>${r.category==='hint'?'A permanent extra tool; regular hints remain free.':r.category==='decoration'?'A collectible displayed on your profile.':r.category==='pet'?'A named accessory badge for Pip’s card.':r.category==='theme'?'Changes your workspace background.':'Choose a short success animation.'}</small><button class="secondary space" ${equipped?'disabled':''} data-${own?'equip':'buy'}="${r.id}">${equipped?'In use':own?'Use reward':'Buy reward'}</button></article>`}).join('')}</div>`}
function emailRoster(){return `<section class="card space"><h2>School email sign-in</h2><p>Connect a rostered student to Microsoft, Google or an emailed sign-in code. Provider names: azure, google, email. This matches verified accounts; entering an email alone never signs anyone in.</p><button id="emailTemplate" class="secondary space">Download student email template</button><form id="emailRoster" class="space"><label>Email roster CSV<input type="file" id="emailFile" accept=".csv" required></label><button>Save email roster</button></form></section>`}
function studyMinutes(id){const d=state.progress.find(p=>p.id==='study-time'&&p.student_id===id)?.data||{};return Math.round(Object.entries(d).filter(([k,v])=>k!=='lastTick'&&typeof v==='number').reduce((n,[k,v])=>n+v,0)/60)}
function applyRewards(){document.body.dataset.product=product;document.body.style.backgroundColor='';const chosen=rewards.find(r=>r.id===wallet?.equipped?.theme);if(student()&&chosen)document.body.style.backgroundColor=chosen.colour;const deco=rewards.find(r=>r.id===wallet?.equipped?.decoration);if(student()&&deco){const el=document.createElement('span');el.className='badge';el.textContent=deco.name;document.querySelector('.actions')?.prepend(el)}}
function celebrate(){if(window.matchMedia('(prefers-reduced-motion: reduce)').matches||localStorage.getItem('onehome-motion')==='off')return;const el=document.createElement('div');el.className='confetti';el.setAttribute('aria-hidden','true');el.textContent=wallet?.equipped?.celebration==='reward-24'?'○ · ○ · ○':wallet?.equipped?.celebration==='reward-25'?'▪ ▪ ▪ ▪ ▪':'✦ · ✦ · ✦';document.body.append(el);setTimeout(()=>el.remove(),1000)}
function bindExtras(){
 document.querySelectorAll('[data-care]').forEach(b=>b.onclick=()=>run(async()=>{wallet=await call('care',{kind:b.dataset.care});render();toast('Pip says thank you!')},b));
 document.querySelectorAll('[data-saving]').forEach(f=>f.onsubmit=e=>{e.preventDefault();const direction=e.submitter.value;run(async()=>{wallet=await call('save_points',{service:f.dataset.saving,amount:Number(new FormData(f).get('amount'))*(direction==='withdraw'?-1:1)});render()},e.submitter)});
 for(const action of ['buy','equip'])document.querySelectorAll(`[data-${action}]`).forEach(b=>b.onclick=()=>run(async()=>{wallet=await call(action,{reward:b.dataset[action]});render();toast(action==='buy'?'Reward added to your collection.':'Reward is now in use.')},b));
 by('emailTemplate')?.addEventListener('click',()=>download('OneHome-email-roster.csv',csv([['id','email','provider'],...state.students.map(s=>[s.id,s.email||'',s.provider||'azure'])]),'text/csv'));
 by('emailRoster')?.addEventListener('submit',e=>{e.preventDefault();run(async()=>{const f=by('emailFile').files[0];if(f.size>2000000)throw Error('Choose a CSV under 2 MB.');const {parseCSV}=await import('./home-core.mjs');const lines=parseCSV(await f.text()),headers=lines.shift().map(v=>v.trim().toLowerCase());if(!['id','email','provider'].every(h=>headers.includes(h)))throw Error('Use the downloaded template headers.');const rows=lines.map(row=>Object.fromEntries(headers.map((h,i)=>[h,row[i]?.trim()||''])));await call('email_roster',{rows});await refresh();toast('Email roster saved.')},e.submitter)});
 by('backReading')?.addEventListener('click',()=>{view='read';feedback=null;render()});
 for(const [id,tool] of [['sneakyHint','shop'],['petHelp','pet']])by(id)?.addEventListener('click',e=>run(async()=>{const h=await call('hint',{id:opened.id,question,tool,...(opened.task?{task:opened.task}:{})});opened.eliminated??={};opened.eliminated[question]=h.eliminate;render();toast('One option ruled out. You can do the rest!')},e.currentTarget));
 by('exampleHint')?.addEventListener('click',()=>{toast('Method guide: write down what you know, identify the operation, work one step at a time, then check by reversing your calculation. For example, if x + 3 = 8, subtract 3 from both sides: x = 5.')});
 const footer=document.querySelector('footer');if(student()&&footer){const b=document.createElement('button');b.className='quiet';b.textContent=localStorage.getItem('onehome-motion')==='off'?'Celebrations: off':'Celebrations: on';b.onclick=()=>{localStorage.setItem('onehome-motion',localStorage.getItem('onehome-motion')==='off'?'on':'off');render()};footer.append(' ',b)}
}
function bindSignIn(){const checkSchool=()=>{const schoolValue=new FormData(by('signin')).get('school');if(!schoolValue||schoolValue!==slug){sessionStorage.setItem('onehome-mode','student');location.href='?school='+encodeURIComponent(schoolValue||'');return false}return true};for(const [id,provider] of [['microsoftLogin','azure'],['googleLogin','google']])by(id)?.addEventListener('click',e=>run(async()=>{if(checkSchool())await oauth(provider)},e.currentTarget));by('emailLogin')?.addEventListener('click',e=>run(async()=>{if(!checkSchool())return;await emailCode(by('studentEmail').value.trim());toast('Check your school inbox for the sign-in code.')},e.currentTarget));by('verifyEmail')?.addEventListener('click',e=>run(async()=>{if(!checkSchool())return;await verifyEmail(by('studentEmail').value.trim(),by('emailToken').value.trim());mode='student';code='';state=null;await refresh()},e.currentTarget))}
for(const event of ['pointerdown','keydown','scroll'])document.addEventListener(event,()=>lastActivity=Date.now(),{passive:true});
setInterval(()=>{if(student()&&opened&&!document.hidden&&!paused&&Date.now()-lastActivity<60000&&['read','quiz'].includes(view))call('tick',{id:opened.id,task:opened.task||undefined,seconds:15}).catch(()=>{})},15000);
